//! Runtime for inflection crates generated by `flexion-train`.
//!
//! A generated crate (`english`, `russian`, …) is a thin typed API over one
//! [`Model`]: per part of speech, the **edits** that turn a lemma into its
//! forms, the **inflection classes** (one edit per cell, plus inherent
//! features such as gender), and a **suffix tree** over lemmas read from
//! their last letter backwards. Each tree node holds a probability
//! distribution over classes; walking a word to its deepest matching node
//! gives the classes that word most likely belongs to. Attested exceptions
//! are simply deep nodes, so memorized words and general patterns are one
//! structure.
//!
//! The engine ([`Pos`]) reads a part of speech through the [`PosModel`]
//! trait. A generated crate implements it in Rust code (its tree is `match`es
//! over the word's letters); the trainer implements it with in-memory
//! [`Tables`]. Every function here is total and never panics.

#![deny(clippy::arithmetic_side_effects)]

mod pos;
pub mod tables;
pub mod text;

pub use pos::{Citation, Edit, Pos};
pub use sound_law;
pub use tables::{Built, Class, Dist, Join, Path, PosModel, Tables};
pub use text::{Casing, Spelling, SpellingStrings, VowelSet, Word};

/// No edit (the class has no form in this cell), or no lemma cell.
pub const NONE: u32 = u32::MAX;
/// Unknown inherent-feature value.
pub const UNKNOWN: u8 = u8::MAX;
/// The symbol that ends every key in the tree: the start of the word, since
/// keys are walked from the last letter backwards.
pub const BOUNDARY: char = '\u{1}';
/// The first syllable-count token; bucket `k` is `char::from_u32(SYLLABLE_TOKEN + k)`.
pub const SYLLABLE_TOKEN: u32 = 0x10;
/// The first-letter token for letter `c` is `char::from_u32(INITIAL_TOKEN + c)`
/// (a private-use plane, so it never meets a letter).
pub const INITIAL_TOKEN: u32 = 0x10_0000;
/// Entries of one node a query reads once it has found a form: entries are
/// sorted by weight, and the root of a part of speech with thousands of
/// word-specific classes would otherwise be read whole for a word no deeper
/// class fits. The trainer prunes with the same limit.
pub const MAX_SCAN: usize = 256;

/// The first of the characters edits carry to set off a part of speech's
/// sound laws (see [`PosModel::phonology`]); they are never written.
pub const TRIGGER_FIRST: char = '\u{E000}';
/// The last trigger character.
pub const TRIGGER_LAST: char = '\u{E0FF}';

/// Whether `c` is a trigger character.
pub fn is_trigger(c: char) -> bool {
    (TRIGGER_FIRST..=TRIGGER_LAST).contains(&c)
}

/// A form as written: `built` (an edit's prefix, the kept stem and its
/// suffix) with the sound laws its triggers set off applied. Without
/// triggers, or without sound laws, `built` itself.
pub fn realize<'b>(
    phonology: Option<&sound_law::Program>,
    built: &'b str,
) -> std::borrow::Cow<'b, str> {
    match phonology {
        Some(p) if built.chars().any(is_trigger) => std::borrow::Cow::Owned(p.apply(built)),
        _ => std::borrow::Cow::Borrowed(built),
    }
}

/// How a form's stress is placed, relative to the edit that built it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Stress {
    /// No stress mark.
    Unmarked,
    /// On the same vowel as the lemma's stress.
    SameAsLemma,
    /// On the n-th vowel of the added suffix.
    Added(u8),
    /// On the n-th vowel of the kept stem, counted from its end (0 = last).
    KeptFromEnd(u8),
    /// On the n-th vowel of the kept stem, counted from its start.
    KeptFromStart(u8),
    /// On the n-th vowel of the added prefix.
    Prefix(u8),
    /// On the n-th vowel from the end of the whole form (0 = last): accents
    /// counted from the word's end, like a recessive accent.
    FromEnd(u8),
}

/// One possible form, with the model's confidence in it.
#[derive(Debug, Clone, PartialEq)]
pub struct Candidate {
    pub form: String,
    /// Probability in `0.0..=1.0`. Candidates of one call sum to 1.
    pub confidence: f32,
}

/// Output options shared by every query.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Options {
    /// Write stress marks (Russian stress, Greek accents).
    pub stress: bool,
    /// Write the letters the spelling can write plain with their marks
    /// (Latin macrons, Greek length marks). Off writes them plain.
    pub marks: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            stress: true,
            marks: true,
        }
    }
}

/// A model: a language's spelling and its parts of speech.
pub struct Model<'a> {
    pub(crate) spelling: Spelling<'a>,
    parts: Vec<&'a dyn PosModel>,
    /// Per part of speech, the readings its derived lexicon reads keys with,
    /// built on first use.
    readings: Vec<std::sync::OnceLock<pos::Readings>>,
}

impl std::fmt::Debug for Model<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Model")
            .field("spelling", &self.spelling)
            .field("parts", &self.parts.len())
            .finish()
    }
}

/// How a key is turned into the sequence of symbols the tree is walked with.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Walk {
    /// Insert a syllable-count token after this many letters (from the end).
    pub syllable_depth: Option<usize>,
    /// Syllable counts above this share the last bucket.
    pub syllable_max: usize,
    /// Insert the word's first letter as a token after this many letters
    /// (from the end), for classes that change the start of the word.
    pub initial_depth: Option<usize>,
}

impl Walk {
    /// The token for a key's syllable count.
    pub fn syllable_token(self, groups: usize) -> char {
        u32::try_from(groups.min(self.syllable_max))
            .ok()
            .and_then(|b| char::from_u32(SYLLABLE_TOKEN.saturating_add(b)))
            .unwrap_or(BOUNDARY)
    }

    /// The token for a key's first letter.
    pub fn initial_token(key: &str) -> char {
        key.chars()
            .next()
            .and_then(|c| char::from_u32(INITIAL_TOKEN.saturating_add(u32::from(c))))
            .unwrap_or(BOUNDARY)
    }

    /// The walk for `key`: its letters from the last one back, the syllable
    /// and first-letter tokens where configured, then the start-of-word
    /// symbol.
    pub fn symbols(self, sp: &Spelling<'_>, key: &str) -> Vec<char> {
        let letters: Vec<char> = key.chars().rev().collect();
        let mut tokens: Vec<(usize, char)> = Vec::new();
        if let Some(d) = self.syllable_depth {
            tokens.push((
                d.min(letters.len()),
                self.syllable_token(sp.vowel_groups(key)),
            ));
        }
        if let Some(d) = self.initial_depth {
            tokens.push((d.min(letters.len()), Walk::initial_token(key)));
        }
        // At equal depths the syllable token comes first.
        tokens.sort_by_key(|t| t.0);
        let mut out = Vec::with_capacity(letters.len().saturating_add(3));
        let mut next = tokens.iter().peekable();
        for (i, &c) in letters.iter().enumerate() {
            while let Some(&&(d, t)) = next.peek() {
                if d != i {
                    break;
                }
                out.push(t);
                next.next();
            }
            out.push(c);
        }
        out.extend(next.map(|&(_, t)| t));
        out.push(BOUNDARY);
        out
    }
}

impl<'a> Model<'a> {
    /// A model over `parts`, in the order the language's config declares
    /// them (helper models after).
    pub fn new(spelling: Spelling<'a>, parts: Vec<&'a dyn PosModel>) -> Model<'a> {
        let readings = parts.iter().map(|_| std::sync::OnceLock::new()).collect();
        Model {
            spelling,
            parts,
            readings,
        }
    }

    pub fn spelling(&self) -> &Spelling<'a> {
        &self.spelling
    }

    /// Part of speech `index`, in the order the language's config declares them.
    pub fn pos(&self, index: usize) -> Option<Pos<'_, 'a>> {
        Some(Pos::new(self, *self.parts.get(index)?, index))
    }

    pub fn pos_count(&self) -> usize {
        self.parts.len()
    }
}

